insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','{"title":"A brighter walk home starts here","summary":"Light the public path from the Eastbridge campus gate to the bus stop before winter evening classes.","problem":"Evening classes finish after sunset, but the public path from the Eastbridge campus gate to the bus shelter has gaps between lights. Students want to see the route clearly and wait for the bus without standing in the dark. The student path audit illustrates the concern; it is sample evidence, not a measured safety study.","action":"Assess the public path from the Eastbridge campus gate to the bus shelter and publish a pedestrian-lighting plan before winter evening classes.","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2026-10-12","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',684,28,42,'2026-09-23T06:11:25.856Z') on conflict(id) do nothing;
insert into public.petition_sources(petition_id,label,url) select '20000000-0000-4000-8000-000000000001','Sample student path audit — illustrative evidence','https://example.org/student-path-audit' where not exists(select 1 from public.petition_sources where petition_id='20000000-0000-4000-8000-000000000001' and url='https://example.org/student-path-audit');
insert into public.petition_updates(petition_id,author_id,body) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','We shared the student path audit and 500 sample signatures at the listening session. Next milestone: 750 voices. We are asking for a published lighting plan before winter evening classes.' where not exists(select 1 from public.petition_updates where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_edits(petition_id,author_id,body,previous_content) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','Clarified the requested action: lighting assessment and a public implementation plan. No eligibility rules changed.','{"title":"A brighter walk home starts here","summary":"Light the public path from the Eastbridge campus gate to the bus stop before winter evening classes.","problem":"Evening classes finish after sunset, but the public path from the Eastbridge campus gate to the bus shelter has gaps between lights. Students want to see the route clearly and wait for the bus without standing in the dark. The student path audit illustrates the concern; it is sample evidence, not a measured safety study.","action":"Assess the public path from the Eastbridge campus gate to the bus shelter and publish a pedestrian-lighting plan before winter evening classes.","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2026-10-12","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb where not exists(select 1 from public.petition_edits where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_endorsements(petition_id,community_id,body) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Riverton students supports this proposal. Sample community endorsement.') on conflict do nothing;
insert into public.discussion_posts(petition_id,author_id,kind,body) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','question','Could the assessment also consider the stretch beside the bus shelter?' where not exists(select 1 from public.discussion_posts where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_deliveries(id,petition_id,delivered_by,recipient,method,note,signature_count,signatories,created_at) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','Riverton Public Works (fictional)','in_person','Sample hand-off of the student path audit at a community listening session.',500,'[]'::jsonb,'2026-09-23T06:11:25.856Z') on conflict(id) do nothing;
insert into public.official_responses(petition_id,author_id,body,organization,verification,delivery_id) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','We will include the campus path in our next lighting review and invite student input. This is a fictional response for demonstration only.','Riverton Public Works (fictional)','verified','30000000-0000-4000-8000-000000000001' where not exists(select 1 from public.official_responses where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','{"title":"More shade. Cooler school days.","summary":"Plant shade trees around the Riverton school courtyard and publish a maintenance plan.","problem":"Students use the school courtyard for breaks and outdoor activities, but the seating area has little shade. The request asks the district to assess suitable planting sites and explain how new trees would be cared for.","action":"Plant shade trees around the Riverton school courtyard","recipient":"Riverton Unified School Board (fictional)","topic":"Environment","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000002","goal":500,"deadline":"2026-11-28","evidence":[],"verification":"account","identities":["first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',328,31,39,'2026-09-22T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000004','{"title":"Keep the library open after class","summary":"Keep the Brookside public library open until 7 pm on school nights.","problem":"Students who need a quiet place after class cannot use the Brookside library once it closes for the day. An evening-hours pilot would give them a predictable place to study; staffing and costs need a public review.","action":"Extend the Brookside library study hours to 7 pm","recipient":"Brookside Library Board (fictional)","topic":"Education","city":"Brookside, CA","communityId":"10000000-0000-4000-8000-000000000004","goal":750,"deadline":"2027-01-14","evidence":[],"verification":"account","identities":["full_name","anonymous"],"customRule":""}'::jsonb,'active',412,34,36,'2026-09-21T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003','{"title":"A park that welcomes every body","summary":"Create an accessible entrance to Willow Park and publish a route plan.","problem":"The current route into Willow Park is difficult for visitors using mobility devices. Residents are asking the parks department to assess the entrance, choose an accessible route and share when improvements could be made.","action":"Add an accessible entrance to Willow Park","recipient":"Riverton Parks and Recreation (fictional)","topic":"Accessibility","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000003","goal":400,"deadline":"2027-03-02","evidence":[],"verification":"community","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',237,37,33,'2026-09-20T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000005','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000004','{"title":"Make room for a neighborhood garden","summary":"Check ownership of the Oak Street lot before proposing a neighborhood garden there.","problem":"Neighbors have suggested the Oak Street lot for a shared garden, but its ownership and suitability have not been established. A public feasibility review would show whether a garden is possible and who must approve it.","action":"Check who owns the Oak Street lot and publish a feasible community-garden plan","recipient":"Brookside Parks and Recreation (fictional)","topic":"Public spaces","city":"Brookside, CA","communityId":"10000000-0000-4000-8000-000000000004","goal":300,"deadline":"2027-04-18","evidence":[],"verification":"location","identities":["first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',156,40,30,'2026-09-19T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000006','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','{"title":"Safer crossings for smaller footsteps","summary":"Assess a raised crosswalk near Eastbridge School and publish the street design.","problem":"Families cross the public street near Eastbridge School at busy arrival and dismissal times. They want the city to review a raised crossing and explain what design would make the route clearer for children.","action":"Add a raised crosswalk near Eastbridge School","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":800,"deadline":"2027-06-04","evidence":[],"verification":"community","identities":["full_name","anonymous"],"customRule":""}'::jsonb,'active',521,43,27,'2026-09-18T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','{"title":"Refill, reuse, repeat","summary":"Install water refill stations at Riverton recreation centers.","problem":"Visitors to recreation centers need a dependable way to refill water bottles during activities. The request asks the parks department to identify suitable sites, costs and a maintenance schedule.","action":"Install water refill stations at Riverton recreation centers","recipient":"Riverton Parks and Recreation (fictional)","topic":"Environment","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000002","goal":500,"deadline":"2027-07-21","evidence":[],"verification":"account","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',189,46,24,'2026-09-17T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003','{"title":"A quiet place to learn","summary":"Make a sensory-friendly study room available at the Riverton public library.","problem":"A shared library room can be noisy for residents who need a lower-stimulation place to read or study. The library board can assess an existing room and publish hours and access guidelines.","action":"Create a sensory-friendly study room at the town library","recipient":"Riverton Library Board (fictional)","topic":"Education","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000003","goal":200,"deadline":"2026-11-10","evidence":[],"verification":"email","identities":["first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',88,49,21,'2026-09-16T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000004','{"title":"Our bus stops need a seat","summary":"Add accessible benches at Brookside bus stops with long waits.","problem":"Some Brookside stops lack a place to sit while waiting for a bus. Riders with limited stamina need the city to assess clear sidewalk space and choose bench sites that preserve accessible travel paths.","action":"Add accessible benches at Brookside bus stops","recipient":"Brookside Public Works (fictional)","topic":"Accessibility","city":"Brookside, CA","communityId":"10000000-0000-4000-8000-000000000004","goal":500,"deadline":"2026-12-27","evidence":[],"verification":"account","identities":["full_name","anonymous"],"customRule":""}'::jsonb,'active',304,52,18,'2026-09-15T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000004','{"title":"Bring the courts back to life","summary":"Repair the Cedar Commons basketball courts and share a reopening plan.","problem":"Neighbors want to use the Cedar Commons courts, but worn playing surfaces need a maintenance assessment. Brookside Parks can inspect the site and publish a repair schedule and reopening criteria.","action":"Repair the basketball courts at Cedar Commons","recipient":"Brookside Parks and Recreation (fictional)","topic":"Public spaces","city":"Brookside, CA","communityId":"10000000-0000-4000-8000-000000000004","goal":250,"deadline":"2027-02-12","evidence":[],"verification":"custom","identities":["full_name","first_name_last_initial","anonymous"],"customRule":"Regular users of this public facility may request organizer review. Do not submit private documents."}'::jsonb,'active',143,55,15,'2026-09-14T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000001','{"title":"Bike to school with confidence","summary":"Pilot a protected bike lane on College Avenue and publish the traffic review.","problem":"Students biking on College Avenue share space with turning vehicles. They want the city to study a protected lane, consult people who use the street and publish a pilot design.","action":"Pilot a protected bike lane along College Avenue","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":600,"deadline":"2027-03-31","evidence":[],"verification":"location","identities":["first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',391,58,12,'2026-09-13T06:11:25.857Z') on conflict(id) do nothing;
insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000002','{"title":"Less waste at lunchtime","summary":"Test food-scrap collection in Eastbridge campus dining halls.","problem":"Campus dining produces food scraps that students would like to keep out of general waste. A limited collection pilot could measure participation and the work required before any campuswide rollout.","action":"Pilot a food-scrap collection program in campus dining halls","recipient":"Eastbridge Campus Facilities (fictional)","topic":"Environment","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000002","goal":200,"deadline":"2027-05-17","evidence":[],"verification":"custom","identities":["full_name","anonymous"],"customRule":"Regular users of this public facility may request organizer review. Do not submit private documents."}'::jsonb,'active',76,61,9,'2026-09-12T06:11:25.857Z') on conflict(id) do nothing;
